index 000000000..bd09f7abe
--- /dev/null
+++ b/applets/timer/autotests/stopwatchtest.cpp
@@ -0,0 +1,124 @@
+/*
+    SPDX-FileCopyrightText: 2026 Peder Bergan <contact@pederbe.dev>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "../stopwatch.h"
+
+#include <QSignalSpy>
+#include <QTest>
+
+class StopwatchTest : public QObject
+{
+    Q_OBJECT
+
+private Q_SLOTS:
+    void lifecycle()
+    {
+        Stopwatch stopwatch;
+        QCOMPARE(stopwatch.elapsed(), 0);
+        QVERIFY(!stopwatch.running());
+        QCOMPARE(stopwatch.text(), QStringLiteral("00:00:00"));
+
+        stopwatch.start();
+        QVERIFY(stopwatch.running());
+        QTest::qSleep(40);
+        stopwatch.start(); // Starting an already running stopwatch must not discard
+                           // time.
+        QTest::qSleep(40);
+        stopwatch.pause();
+        QVERIFY(!stopwatch.running());
+        const qint64 paused = stopwatch.elapsed();
+        QVERIFY(paused >= 80);
+        QTest::qSleep(40);
+        QCOMPARE(stopwatch.elapsed(), paused);
+
+        stopwatch.start();
+        QTest::qSleep(40);
+        stopwatch.pause();
+        QVERIFY(stopwatch.elapsed() >= paused + 40);
+        stopwatch.reset();
+        QCOMPARE(stopwatch.elapsed(), 0);
+        QVERIFY(!stopwatch.running());
+
+        stopwatch.start();
+        stopwatch.reset();
+        QVERIFY(!stopwatch.running());
+        QCOMPARE(stopwatch.elapsed(), 0);
+    }
+
+    void delayedUpdates()
+    {
+        Stopwatch stopwatch;
+        QSignalSpy updates(&stopwatch, &Stopwatch::elapsedChanged);
+        stopwatch.start();
+        updates.clear();
+        QTest::qSleep(2100); // No event-loop callbacks run during this delay.
+        QCOMPARE(updates.count(), 0);
+        QVERIFY(stopwatch.elapsed() >= 2100);
+        QTRY_VERIFY(!updates.isEmpty());
+        stopwatch.pause();
+    }
+
+    void independentInstances()
+    {
+        Stopwatch first;
+        Stopwatch second;
+        first.start();
+        QTest::qSleep(40);
+        first.pause();
+        QVERIFY(first.elapsed() > 0);
+        QCOMPARE(second.elapsed(), 0);
+        QVERIFY(!second.running());
+        second.restore(1234);
+        second.reset();
+        QVERIFY(first.elapsed() > 0);
+    }
+
+    void fractionalResumeUpdate()
+    {
+        Stopwatch stopwatch;
+        stopwatch.restore(800);
+        QSignalSpy updates(&stopwatch, &Stopwatch::elapsedChanged);
+        stopwatch.start();
+        updates.clear();
+        // Notify at the next elapsed second, including a partially completed second.
+        QVERIFY(updates.wait(650));
+        QVERIFY(stopwatch.elapsed() >= 1000);
+        stopwatch.pause();
+        updates.clear();
+        QVERIFY(!updates.wait(250));
+    }
+
+    void restore_data()
+    {
+        QTest::addColumn<qint64>("elapsed");
+        QTest::addColumn<QString>("text");
+        QTest::newRow("negative") << qint64(-1) << QStringLiteral("00:00:00");
+        QTest::newRow("subsecond") << qint64(999) << QStringLiteral("00:00:00");
+        QTest::newRow("seconds") << qint64(1234) << QStringLiteral("00:00:01");
+        QTest::newRow("day") << qint64(86400000) << QStringLiteral("24:00:00");
+        QTest::newRow("hundred-hours") << qint64(360123999) << QStringLiteral("100:02:03");
+    }
+
+    void restore()
+    {
+        QFETCH(qint64, elapsed);
+        QFETCH(QString, text);
+        Stopwatch stopwatch;
+        stopwatch.start();
+        stopwatch.restore(elapsed);
+        QVERIFY(!stopwatch.running());
+        QCOMPARE(stopwatch.elapsed(), qMax<qint64>(0, elapsed));
+        QCOMPARE(stopwatch.text(), text);
+        stopwatch.start();
+        QTest::qSleep(20);
+        stopwatch.pause();
+        QVERIFY(stopwatch.elapsed() >= qMax<qint64>(0, elapsed) + 20);
+    }
+};
+
+QTEST_GUILESS_MAIN(StopwatchTest)
+
+#include "stopwatchtest.moc"
