+*/
+
+#include "stopwatch.h"
+
+#include <limits>
+
+Stopwatch::Stopwatch(QObject *parent)
+    : QObject(parent)
+{
+    m_updateTimer.setSingleShot(true);
+    m_updateTimer.setTimerType(Qt::PreciseTimer);
+    connect(&m_updateTimer, &QTimer::timeout, this, [this] {
+        Q_EMIT elapsedChanged();
+        if (running()) {
+            m_updateTimer.start(1000 - static_cast<int>(elapsed() % 1000));
+        }
+    });
+}
+
+bool Stopwatch::running() const
+{
+    return m_clock.isValid();
+}
+
+qint64 Stopwatch::elapsed() const
+{
+    // QElapsedTimer uses a monotonic clock. On Linux, time spent suspended is excluded.
+    const qint64 segment = running() ? m_clock.elapsed() : 0;
+    return m_elapsed + qMin(segment, std::numeric_limits<qint64>::max() - m_elapsed);
+}
+
+QString Stopwatch::text() const
+{
+    const qint64 seconds = elapsed() / 1000;
+    return QStringLiteral("%1:%2:%3")
+        .arg(seconds / 3600, 2, 10, QLatin1Char('0'))
+        .arg((seconds / 60) % 60, 2, 10, QLatin1Char('0'))
+        .arg(seconds % 60, 2, 10, QLatin1Char('0'));
+}
+
+void Stopwatch::start()
+{
+    if (running()) {
+        return;
+    }
+    m_clock.start();
+    m_updateTimer.start(1000 - static_cast<int>(elapsed() % 1000));
+    Q_EMIT runningChanged();
+    Q_EMIT elapsedChanged();
+}
+
+void Stopwatch::pause()
+{
+    if (!running()) {
+        return;
+    }
+    m_elapsed = elapsed();
+    m_clock.invalidate();
+    m_updateTimer.stop();
+    Q_EMIT runningChanged();
+    Q_EMIT elapsedChanged();
+}
+
+void Stopwatch::reset()
+{
+    restore(0);
+}
+
+void Stopwatch::restore(qint64 elapsed)
+{
+    const bool wasRunning = running();
+    m_clock.invalidate();
+    m_updateTimer.stop();
+    m_elapsed = qMax<qint64>(0, elapsed);
+    if (wasRunning) {
+        Q_EMIT runningChanged();
+    }
+    Q_EMIT elapsedChanged();
+}
